import 'package:flutter/painting.dart';

import 'bot_roster.dart';

/// The avatar set: a player's avatar is one of these ids, carried in [PlayerInfo.avatar] (and
/// so synced to online players). Picture avatars are asset paths; the rest of the slots are
/// "letter" avatars, `color:N`: the player's initial on palette colour N.
///
/// Picture avatars come first: the drawn set (assets/avatars/, see tool/avatars), then the
/// robots. Bots use the robots.
const kAvatarArt = <String>[
  // Generated by tool/avatars/make_avatars.py from the artwork: keep in the picker order.
  'assets/avatars/punk_pig.png',
  'assets/avatars/wizard_cow.png',
  'assets/avatars/dog_white_hat.png',
  'assets/avatars/grumpy_cat.png',
  'assets/avatars/sun.png',
  'assets/avatars/sleepy_moon.png',
  'assets/avatars/horse_carrot.png',
  'assets/avatars/sunflower.png',
  'assets/avatars/coffee_mug.png',
  'assets/avatars/skull.png',
  'assets/avatars/ghost.png',
  'assets/avatars/raccoon.png',
  'assets/avatars/parrot.png',
  'assets/avatars/fox.png',
  'assets/avatars/hamster.png',
  'assets/avatars/cactus.png',
];

/// How many slots the picker shows.
const kAvatarSlots = 48;

/// Letter avatar colours (warm, readable under white text).
final List<Color> avatarPalette = [
  for (var i = 0; i < kAvatarSlots; i++) HSVColor.fromAHSV(1, (i * 47) % 360 * 1.0, .55 + (i % 3) * .1, .45 + (i % 4) * .08).toColor(),
];

/// Every avatar in the picker, in order.
List<String> get avatarChoices {
  final pics = [...kAvatarArt, for (final r in robotRoster) r.avatar];
  return [...pics, for (var i = 0; pics.length + i < kAvatarSlots; i++) 'color:$i'];
}

bool isKnownAvatar(String? id) => id != null && avatarChoices.contains(id);

/// The asset for a picture avatar, or null.
String? avatarImage(String? id) => id != null && id.startsWith('assets/') ? id : null;

/// The colour of a letter avatar, or null.
Color? avatarColor(String? id) {
  if (id == null || !id.startsWith('color:')) return null;
  final i = int.tryParse(id.substring(6));
  return i == null ? null : avatarPalette[i % avatarPalette.length];
}
